    "question": "Q430. [Advanced NEET Challenge] In the Hell-Volhard-Zelinsky (HVZ) reaction, carboxylic acids having an $\\alpha$-hydrogen react with chlorine or bromine in the presence of red phosphorus to yield:",
    "options": {
      "A": "Acid chlorides",
      "B": "$\\alpha$-Halocarboxylic acids",
      "C": "$\beta$-Halocarboxylic acids",
      "D": "Alkanes"
    },
