    "id": "ald-mcq-450",
    "questionNumber": 450,
    "question": "Q450. [Advanced NEET Challenge] In the Hell-Volhard-Zelinsky (HVZ) reaction, carboxylic acids having an $\\alpha$-hydrogen react with chlorine or bromine in the presence of red phosphorus to yield:",
    "options": {
      "A": "Acid chlorides",
      "B": "$\\alpha$-Halocarboxylic acids",
      "C": "$\beta$-Halocarboxylic acids",
      "D": "Alkanes"
    },
    "optionsList": [
      "Acid chlorides",
      "$\\alpha$-Halocarboxylic acids",
      "$\beta$-Halocarboxylic acids",
      "Alkanes"
    ],
    "correctAnswer": "B",
    "correctIndex": 1,
    "explanation": "1. CONCEPT & PRINCIPLE:\nSelective alpha-halogenation of carboxylic acids (HVZ reaction).\n\n2. GIVEN INFORMATION / DATA:\nCarboxylic acid with $\\alpha$-hydrogen: $R-CH_2-COOH + X_2 / \\text{red P} \\xrightarrow{H_2O} R-CH(X)-COOH$.\n\n3. FORMULA / EQUATION:\nCatalytic red P generates $PX_3$ in situ, forming acyl halide intermediate that enolizes readily for alpha-halogenation.\n\n4. STEP-BY-STEP REASONING & CALCULATION:\n1. Carboxylic acids containing at least one $\\alpha$-hydrogen atom react with chlorine or bromine in the presence of a catalytic amount of red phosphorus.\n2. Phosphorus reacts with halogen to generate $PBr_3$ or $PCl_3$, which converts a small amount of acid to acyl halide ($R-CH_2-COX$).\n3. The acyl halide enolizes much more rapidly than the carboxylic acid, allowing halogenation to occur specifically and exclusively at the $\\alpha$-carbon.\n4. Exchange with unreacted carboxylic acid regenerates acyl halide and yields the final $\\alpha$-halocarboxylic acid: $R-CH(X)-COOH$.\n5. This is the Hell-Volhard-Zelinsky (HVZ) reaction.\n\n5. FINAL CONCLUSION:\n$\\alpha$-Halocarboxylic acids\n\n6. OPTION ANALYSIS & COMMON TRAPS:\nAcids lacking $\\alpha$-hydrogens (e.g., $HCOOH, C_6H_5COOH$) do not undergo this reaction; halogenation does not occur at $\\beta$-position.",
    "solutionStructured": {
      "concept": "Selective alpha-halogenation of carboxylic acids (HVZ reaction).",
      "given": "Carboxylic acid with $\\alpha$-hydrogen: $R-CH_2-COOH + X_2 / \\text{red P} \\xrightarrow{H_2O} R-CH(X)-COOH$.",
      "formula": "Catalytic red P generates $PX_3$ in situ, forming acyl halide intermediate that enolizes readily for alpha-halogenation.",
      "stepByStep": "1. Carboxylic acids containing at least one $\\alpha$-hydrogen atom react with chlorine or bromine in the presence of a catalytic amount of red phosphorus.\n2. Phosphorus reacts with halogen to generate $PBr_3$ or $PCl_3$, which converts a small amount of acid to acyl halide ($R-CH_2-COX$).\n3. The acyl halide enolizes much more rapidly than the carboxylic acid, allowing halogenation to occur specifically and exclusively at the $\\alpha$-carbon.\n4. Exchange with unreacted carboxylic acid regenerates acyl halide and yields the final $\\alpha$-halocarboxylic acid: $R-CH(X)-COOH$.\n5. This is the Hell-Volhard-Zelinsky (HVZ) reaction.",
      "finalAnswer": "$\\alpha$-Halocarboxylic acids",
      "whyOtherOptionsWrong": "Acids lacking $\\alpha$-hydrogens (e.g., $HCOOH, C_6H_5COOH$) do not undergo this reaction; halogenation does not occur at $\\beta$-position."
    },
