      "given": "Carboxylic acid with $\\alpha$-hydrogen: $R-CH_2-COOH + X_2 / \\text{red P} \\xrightarrow{H_2O} R-CH(X)-COOH$.",
      "formula": "Catalytic red P generates $PX_3$ in situ, forming acyl halide intermediate that enolizes readily for alpha-halogenation.",
      "stepByStep": "1. Carboxylic acids containing at least one $\\alpha$-hydrogen atom react with chlorine or bromine in the presence of a catalytic amount of red phosphorus.\n2. Phosphorus reacts with halogen to generate $PBr_3$ or $PCl_3$, which converts a small amount of acid to acyl halide ($R-CH_2-COX$).\n3. The acyl halide enolizes much more rapidly than the carboxylic acid, allowing halogenation to occur specifically and exclusively at the $\\alpha$-carbon.\n4. Exchange with unreacted carboxylic acid regenerates acyl halide and yields the final $\\alpha$-halocarboxylic acid: $R-CH(X)-COOH$.\n5. This is the Hell-Volhard-Zelinsky (HVZ) reaction.",
